#import "MenuDismissal.h"
int main(){@autoreleasepool{NSArray *frames=@[[NSValue valueWithRect:NSMakeRect(200,200,300,500)],[NSValue valueWithRect:NSMakeRect(500,300,150,150)]];for(NSValue *point in @[[NSValue valueWithPoint:NSMakePoint(250,250)],[NSValue valueWithPoint:NSMakePoint(600,350)]])if([MenuDismissal shouldDismissPoint:point.pointValue menuFrames:frames])return 1;for(NSValue *point in @[[NSValue valueWithPoint:NSMakePoint(100,100)],[NSValue valueWithPoint:NSMakePoint(350,760)]])if(![MenuDismissal shouldDismissPoint:point.pointValue menuFrames:frames])return 2;puts("PASS: root/submenu clicks retained; outside and menu-bar icon points dismiss.");}return 0;}
